import{_ as l,l as n,o as e,c as i,v as t,p as s,x as o,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"重链剖分","description":"","frontmatter":{"title":"重链剖分","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heavy-light.md","filePath":"cs/heavy-light.md","lastUpdated":1789023840000}'),c={name:"cs/heavy-light.md"};function u(_,a,m,D,E,S){const r=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="重链剖分" tabindex="-1">重链剖分 <a class="header-anchor" href="#重链剖分" aria-label="Permalink to &quot;重链剖分&quot;">​</a></h1><div class="epigraph"><p>每条根到叶路径切成 $O(\\log n)$ 条重链；链内 DFS 序连续，路径查询变成序列上 $O(\\log n)$ 段区间。</p><footer>—— 据 Sleator and Tarjan, A Data Structure for Dynamic Trees, 1983 的重边思想；竞赛与教材中的 heavy-light decomposition 整理</footer></div><p>上一课<a href="/cs/tree-binary-lifting">树上倍增与差分</a>处理静态路径和与离线加。线段树、树状数组活在序列上。缺口是把<strong>树上路径</strong>映成序列区间：重链剖分（HLD）。不重写倍增表。本课静态树 + 序列结构；动态换边是 Link-Cut，只点名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>子树大小 \\(sz[u]\\)。对每个 \\(u\\)，重儿子是 \\(sz\\) 最大的孩子，边 \\((u,\\mathrm{son}[u])\\) 为重边；其余轻边。重边串成重链，链顶 <code>top[u]</code>。性质：任意点到根，轻边次数 \\(O(\\log n)\\)——每次轻边走到的子树至少减半。故任意路径 \\(u\\)–\\(v\\) 可拆成 \\(O(\\log n)\\) 条链上的连续段。</p><p>DFS 先走重儿子，则每条重链在 DFS 序里是连续区间。路径查询：当 <code>top[u]\\neq top[v]</code>，把更深链顶的那一段交给序列结构，再跳到 <code>parent[top]</code>。最后同一链上一段。</p><p>缺口是剖分，不是再发明线段树。</p><h3 id="重链不是直径" tabindex="-1">重链不是直径 <a class="header-anchor" href="#重链不是直径" aria-label="Permalink to &quot;重链不是直径&quot;">​</a></h3><p>重边按子树大小，不是边权。直径、最长链是另一回事。Sleator–Tarjan 的动态树用「偏爱边」保持类似重轻，本课静态剖分即可。</p><p><span class="marginnote">HLD 把树路径摊成区间，与 ST 表/线段树对接。Sleator–Tarjan 1983 的 Link-Cut 用 splay 维护优选路径，本课不实现。后课点分治按重心递归，不是按链。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两遍 DFS：第一遍 \\(sz\\) 与重儿子；第二遍链顶与 DFS 序。路径/子树查询：子树是 DFS 序一段；路径如上跳链。修改同步打到序列结构。</p>',12)),(e(),s(h,null,{default:o(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SZ%5B%22%E5%AD%90%E6%A0%91%E5%A4%A7%E5%B0%8F%22%5D%20--%3E%20HVY%5B%22%E9%87%8D%E5%84%BF%E5%AD%90%20%2F%20%E9%87%8D%E9%93%BE%22%5D%0A%20%20HVY%20--%3E%20SEQ%5B%22DFS%20%E5%BA%8F%E8%BF%9E%E7%BB%AD%22%5D%0A%20%20SEQ%20--%3E%20Q%5B%22%E8%B7%AF%E5%BE%84%20%3D%20O(log%20n)%20%E6%AE%B5%E5%8C%BA%E9%97%B4%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>复杂度：剖分 \\(O(n)\\)；每次路径 \\(O(\\log n)\\) 段乘以序列结构的区间代价（常再 \\(\\log n\\)）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>轻边使 \\(sz\\) 减半，故一条根路径上轻边 \\(O(\\log n)\\)，链段数同阶。与倍增比：倍增段数也是 \\(O(\\log n)\\) 但每段是 \\(2^k\\) 祖先跳跃，难接任意区间结构；HLD 的段是真实树边连续，能打懒惰标记。子树修改直接 DFS 序区间，不必走轻边论证。</p><p>不要把「每次跳 <code>top</code>」写成 \\(O(n)\\)：链顶跳跃沿轻边，次数对数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 LCT、不写欧拉旅游树。点分治处理「过某点的路径统计」，与 HLD 的「路径是区间」不同。后课默认：树上路径可剖成对数段序列区间。下一课用重心把距离类统计变成分治。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>重儿子使轻边减半；路径 \\(O(\\log n)\\) 条链。</li><li>链在 DFS 序连续，接线段树。</li><li>静态剖分；动态树另论。</li><li>出处：重轻思想见 Sleator and Tarjan, 1983；剖分实现为标准教材技法。</li></ul>',8))])}const T=l(c,[["render",u]]);export{g as __pageData,T as default};
